<div class="panel"><div class="panel-heading"><div><h2><?= $plan['target']?'Activate':'Deactivate' ?> <?= esc($plan['name']) ?></h2><p>Inspect the dependencies and the expected impact. No changes have been made yet.</p></div><span class="pill"><?= esc($plan['version']) ?></span></div><dl class="bf-plan-details"><dt>Current</dt><dd><?= $plan['current']?'Active':'Disabled' ?></dd><dt>Proposed</dt><dd><?= $plan['target']?'Active':'Disabled' ?></dd><dt>Dependencies</dt><dd><?= esc(implode(', ',array_keys($plan['dependencies']))?:'None') ?></dd><dt>Dependants</dt><dd><?= esc(implode(', ',$plan['dependants'])?:'None') ?></dd></dl><div class="bf-info-box"><strong>Operational notes</strong><ul><?php foreach($plan['warnings'] as $warning):?><li><?= esc($warning) ?></li><?php endforeach; ?></ul></div><?php if($plan['changed']):?><form class="form-stack" action="/admin/modules/toggle" method="post"><input type="hidden" name="_csrf" value="<?= esc(\Brightery\Core\App::get()->service(\Brightery\Core\Security::class)->csrf()) ?>"><input type="hidden" name="name" value="<?= esc($plan['name']) ?>"><input type="hidden" name="enabled" value="<?= $plan['target']?'1':'0' ?>"><input type="hidden" name="plan_token" value="<?= esc($plan['token']) ?>"><label class="bf-field"><span>Type <strong><?= $plan['target']?'ACTIVATE':'DEACTIVATE' ?> <?= esc($plan['name']) ?></strong> to confirm</span><input name="confirmation" autocomplete="off" required></label><div class="bf-actions"><a class="btn btn-secondary" href="/admin/modules">Cancel</a><button class="btn btn-primary" type="submit">Apply change</button></div></form><?php else:?><p>This module already has the requested state.</p><a class="btn btn-secondary" href="/admin/modules">Back to modules</a><?php endif;?></div>
